    archivesName = mod_id
}

java.toolchain.languageVersion = JavaLanguageVersion.of(25)

neoForge {
    version = project.neo_version

    runs {
        client {
            client()
            systemProperty "neoforge.enabledGameTestNamespaces", project.mod_id
        }

        server {
            server()
            programArgument '--nogui'
            systemProperty 'neoforge.enabledGameTestNamespaces', project.mod_id
        }

        gameTestServer {
            type = "gameTestServer"
            systemProperty 'neoforge.enabledGameTestNamespaces', project.mod_id
        }

        data {
            clientData()
            programArguments.addAll '--mod', project.mod_id, '--all', '--output', file('src/generated/resources/').getAbsolutePath(), '--existing', file('src/main/resources/').getAbsolutePath()
            systemProperty 'neoforge.enabledGameTestNamespaces', project.mod_id
        }

        configureEach {
            systemProperty 'forge.logging.markers', 'REGISTRIES'
            logLevel = org.slf4j.event.Level.DEBUG
        }
    }

    mods {
        "${mod_id}" {
            sourceSet(sourceSets.main)
        }
    }
}

sourceSets.main.resources {
    srcDir 'src/generated/resources'
    exclude '.cache'
}
configurations {
    runtimeClasspath.extendsFrom localRuntime
}

dependencies {
    implementation "curse.maven:agritech-evolved-1287394:9155589"

    compileOnly "org.appliedenergistics:appliedenergistics2:${ae2_version}"
    compileOnly "curse.maven:applied-flux-965012:${appflux_file}"
    compileOnly "maven.modrinth:jade:26.1.12+neoforge"
    if (!project.hasProperty('noJade')) {
        localRuntime "maven.modrinth:jade:26.1.12+neoforge"
    }
    if (!project.hasProperty('noAe2')) {
        localRuntime "org.appliedenergistics:appliedenergistics2:${ae2_version}"
        localRuntime "org.appliedenergistics:guideme:${guideme_version}"
        if (!project.hasProperty('noAppliedFlux')) {
            localRuntime "curse.maven:applied-flux-965012:${appflux_file}"
            localRuntime "curse.maven:glodium-957920:${glodium_file}"
        }
    }

    // Powah gives dev runs a fast FE source and FE cables. The mod has no code for it. Powah needs Cloth Config and GuideME.
    if (!project.hasProperty('noPowah')) {
        localRuntime "maven.modrinth:powah:7.0.4-alpha-neoforge"
        localRuntime "maven.modrinth:cloth-config:26.1.154+neoforge"
        localRuntime "org.appliedenergistics:guideme:${guideme_version}"
    }

    // Oracle Index shows the guide book in dev runs. The mod has no code for it. Oracle Index needs Architectury.
    // z4LDmExp is the Modrinth maven id of the NeoForge 2.0.0 release, because the version number 2.0.0 also names the Fabric jar.
    if (!project.hasProperty('noOracleIndex')) {
        localRuntime "maven.modrinth:oracle-index:z4LDmExp"
        localRuntime "maven.modrinth:architectury-api:20.1.17+neoforge"
    }

    // Logistics Networks lets dev runs check a node on the core. The mod has no code for it. This is the version ATM11 runs.
    if (!project.hasProperty('noLogisticsNetworks')) {
        localRuntime "curse.maven:logistics-networks-1448257:9115811"
    }

    // Structure Lab takes screenshots for the project page. It is a local jar, so it loads only when a path is given.
    if (project.hasProperty('structureLabJar')) {
        localRuntime files(project.property('structureLabJar'))
    }

    testImplementation platform("org.junit:junit-bom:5.13.4")
    testImplementation "org.junit.jupiter:junit-jupiter"
    testImplementation "com.google.code.gson:gson:2.13.2"
    testRuntimeOnly "org.junit.platform:junit-platform-launcher"
}

var generateModMetadata = tasks.register("generateModMetadata", ProcessResources) {
    var replaceProperties = [
            minecraft_version      : minecraft_version,
            minecraft_version_range: minecraft_version_range,
            neo_version            : neo_version,
            loader_version_range   : loader_version_range,
            mod_id                 : mod_id,
            mod_name               : mod_name,
            mod_license            : mod_license,
            mod_version            : mod_version,
    ]
    inputs.properties replaceProperties
    expand replaceProperties
    from "src/main/templates"
    into "build/generated/sources/modMetadata"
}
sourceSets.main.resources.srcDir generateModMetadata
neoForge.ideSyncTask generateModMetadata

tasks.named('test') {
    useJUnitPlatform()
    // The release script and docs tests read these files from the repo instead of the classpath, so Gradle has to track them to rerun those tests after an edit.
    inputs.files('tools', '.github', 'docs/description.md', 'docs/media', 'README.md', 'CHANGELOG.md', 'CONTRIBUTING.md', 'DEVELOPMENT.md')
            .withPropertyName('repoFilesReadByTests')
            .withPathSensitivity(PathSensitivity.RELATIVE)
}

tasks.named('processResources', ProcessResources) {
    from('wiki') {
        into 'assets/oracle_index/books/modular_planters'
    }
}

tasks.named('jar') {
    exclude '**/gametest/**', '**/datagen/**', 'data/modular_planters/structure/empty.nbt'
    from('LICENSE.md', 'LICENSE-ATE.md')
}

// The release workflow's checks build the jar once, and each publish job downloads that jar and passes it here with -PpublishJar, so every site gets the same jar instead of a rebuild.
def publishJar = providers.gradleProperty('publishJar')

publishMods {
    file = publishJar.present ? layout.projectDirectory.file(publishJar.get()) : jar.archiveFile
    changelog = providers.exec {
        commandLine 'bash', file('tools/changelog-section.sh').path, project.version.toString(), file('CHANGELOG.md').path
    }.standardOutput.asText
    displayName = "${mod_name} ${project.version}"
    type = mod_version.contains('-alpha') ? ALPHA : mod_version.contains('-beta') ? BETA : STABLE
    modLoaders.add('neoforge')
    dryRun = providers.environmentVariable('DRY_RUN').present

    github {
        accessToken = REDACTED
        repository = 'julian-perge/ModularPlanters'
        tagName = project.version.toString()
        displayName = project.version.toString()
        commitish = providers.environmentVariable('GITHUB_SHA').orElse('main')
    }

    if (curseforge_project_id) {
        curseforge {
            accessToken = REDACTED
            projectId = curseforge_project_id
            minecraftVersions.add(minecraft_version)
            javaVersions.add(JavaVersion.VERSION_25)
            client = true
            server = true
            requires('agritech-evolved')
            optional('applied-energistics-2', 'applied-flux', 'jade', 'oracle-index', 'logistics-network')
